def solve():
    from z3 import Solver, Int, Or, And, sat
    s = Solver()
    colors = [Int(f'c_{i}') for i in range(1, 55)]
    for c in colors:
        s.add(And(c >= 0, c <= 2))
    for a in range(1, 55):
        for d in range(1, 55):
            if a + 2*d <= 54:
                s.add(Or(colors[a-1] != colors[a+d-1], colors[a-1] != colors[a+2*d-1]))
    if s.check() == sat:
        m = s.model()
        print([m[colors[i]].as_long() for i in range(54)])
    else:
        print("UNSAT")
solve()

